library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use work.wishbone_pkg.all;
use work.wbgenplus_pkg.all;
use work.genram_pkg.all;
use work.complex_demo_auto_pkg.all;

entity complex_demo_auto is
generic(
  g_channels  : natural := 16 --Input channels
);
Port(
  clk_sys_i                 : std_logic;                                        -- Clock input for sys domain
  rst_sys_n_i               : std_logic;                                        -- Reset input (active low) for sys domain
  clk_ref_i                 : std_logic;                                        -- Clock input for ref domain
  rst_ref_n_i               : std_logic;                                        -- Reset input (active low) for ref domain
  status_ref_i              : in  std_logic_vector(g_channels-1 downto 0);      -- tlu 'timestamps pending' bit per channel
  status_V_ref_i            : in  std_logic_vector(1-1 downto 0);               -- Valid flag - status
  cmd_ref_o                 : out std_logic_vector(16-1 downto 0);              -- Cmd for tlu controller
  cmd_fifo_out_pop_ref_i    : in std_logic;
  cmd_fifo_out_empty_ref_o  : out std_logic;
  cnt_i                     : in  matrix(g_channels-1 downto 0, 16-1 downto 0); -- Shows channel timestamp count
  cnt_V_i                   : in  std_logic_vector(1-1 downto 0);               -- Valid flag - cnt
  error_i                   : in  std_logic_vector(1-1 downto 0);               -- Error control
  stall_i                   : in  std_logic_vector(1-1 downto 0);               -- flow control
  ts_out_i                  : in  matrix(g_channels-1 downto 0, 64-1 downto 0); -- Timestamp fifos in. Use RD flag to pop
  ts_out_V_i                : in  std_logic_vector(1-1 downto 0);               -- Valid flag - ts_out
  ch_sel_o                  : out std_logic_vector(8-1 downto 0);               -- Channel select register
  clear_fifo_o              : out matrix(g_channels-1 downto 0, 1-1 downto 0);  -- Clears Fifo
  ts_flags_o                : out matrix(g_channels-1 downto 0, 32-1 downto 0); -- timestamp channel flagbits
  ts_out_RD_o               : out std_logic_vector(1-1 downto 0);               -- Read enable flag - ts_out
  
  data_i                    : in  t_wishbone_slave_in;
  data_o                    : out t_wishbone_slave_out

  
  
  
);
end complex_demo_auto;

architecture rtl of complex_demo_auto is

  signal s_pop, s_push              : std_logic;
  signal s_empty, s_full            : std_logic;
  signal r_e_wait, s_e_p            : std_logic;
  signal s_stall                    : std_logic;
  signal s_valid,
         s_valid_ok,
         r_valid_check              : std_logic;
  signal r_ack                      : std_logic;
  signal r_err                      : std_logic;
  signal s_e, r_e, s_w              : std_logic;
  signal s_d                        : std_logic_vector(32-1 downto 0);
  signal s_s                        : std_logic_vector(4-1 downto 0);
  signal s_a                        : std_logic_vector(7-1 downto 0);
  signal s_a_ext,
         r_a_ext0,
         r_a_ext1                   : std_logic_vector(9-1 downto 0);
  signal r_error                    : std_logic_vector(1-1 downto 0)                := std_logic_vector(to_unsigned(0, 1));           -- Error
  signal s_error_i                  : std_logic_vector(1-1 downto 0)                := (others => '0');                               -- Error control
  signal s_stall_i                  : std_logic_vector(1-1 downto 0)                := (others => '0');                               -- flow control
  signal r_status_V                 : std_logic_vector(1-1 downto 0)                := (others => '0');                               -- Valid flag - status
  signal s_status_V_i               : std_logic_vector(1-1 downto 0)                := (others => '0');                               -- Valid flag - status
  signal r_status                   : std_logic_vector(g_channels-1 downto 0)       := (others => '0');                               -- tlu 'timestamps pending' bit per channel
  signal s_status_i                 : std_logic_vector(g_channels-1 downto 0)       := (others => '0');                               -- tlu 'timestamps pending' bit per channel
  signal r_cmd                      : std_logic_vector(16-1 downto 0)               := (others => '0');                               -- Cmd for tlu controller
  signal s_cmd_o                    : std_logic;
  signal s_cmd_fifo_out_push        : std_logic;
  signal s_cmd_fifo_out_pop         : std_logic;
  signal s_cmd_fifo_out_full        : std_logic;
  signal s_cmd_fifo_out_almost_full : std_logic;
  signal s_cmd_fifo_out_empty       : std_logic;
  signal r_ch_qty                   : std_logic_vector(5-1 downto 0)                := std_logic_vector(to_unsigned(g_channels, 5));  -- Individually controllable flag bits
  signal r_ch_sel                   : std_logic_vector(8-1 downto 0)                := (others => '0');                               -- Channel select register
  signal r_clear_fifo               : matrix(g_channels-1 downto 0, 1-1 downto 0)   := (others => '0');                               -- Clears Fifo
  signal r_ts_out_RD                : std_logic_vector(1-1 downto 0)                := std_logic_vector(to_unsigned(0, 1));           -- Read enable flag - ts_out
  signal r_ts_out_V                 : std_logic_vector(1-1 downto 0)                := (others => '0');                               -- Valid flag - ts_out
  signal s_ts_out_V_i               : std_logic_vector(1-1 downto 0)                := (others => '0');                               -- Valid flag - ts_out
  signal r_ts_out                   : matrix(g_channels-1 downto 0, 64-1 downto 0)  := (others => '0');                               -- Timestamp fifos in. Use RD flag to pop
  signal s_ts_out_i                 : matrix(g_channels-1 downto 0, 64-1 downto 0)  := (others => '0');                               -- Timestamp fifos in. Use RD flag to pop
  signal r_cnt_V                    : std_logic_vector(1-1 downto 0)                := (others => '0');                               -- Valid flag - cnt
  signal s_cnt_V_i                  : std_logic_vector(1-1 downto 0)                := (others => '0');                               -- Valid flag - cnt
  signal r_cnt                      : matrix(g_channels-1 downto 0, 16-1 downto 0)  := (others => '0');                               -- Shows channel timestamp count
  signal s_cnt_i                    : matrix(g_channels-1 downto 0, 16-1 downto 0)  := (others => '0');                               -- Shows channel timestamp count
  signal r_ts_flags                 : matrix(g_channels-1 downto 0, 32-1 downto 0)  := (others => '0');                               -- timestamp channel flagbits


begin

  sp : wb_skidpad
  generic map(
    g_adrbits   => 7
  )
  Port map(
    clk_i        => clk_sys_i,
    rst_n_i      => rst_sys_n_i,
    push_i       => s_push,
    pop_i        => s_pop,
    full_o       => s_full,
    empty_o      => s_empty,
    adr_i        => data_i.adr(8 downto 2),
    dat_i        => data_i.dat,
    sel_i        => data_i.sel,
    we_i         => data_i.we,
    adr_o        => s_a,
    dat_o        => s_d,
    sel_o        => s_s,
    we_o         => s_w
  );

  validmux: with to_integer(unsigned(s_a_ext)) select
  s_valid <= 
  s_status_V_i(0) when c_status_GET,    -- 
  s_ts_out_V_i(0) when c_ts_out_GET_0,  -- 
  s_ts_out_V_i(0) when c_ts_out_GET_1,  -- 
  s_cnt_V_i(0)    when c_cnt_GET,       -- 
  '1'             when others;
  
  s_valid_ok      <=  r_valid_check and s_valid;
  s_e_p           <=  r_e or r_e_wait;
  s_a_ext         <= s_a & "00";
  s_stall         <= s_full;
  s_push          <= data_i.cyc and data_i.stb and not s_stall;
  s_e             <= not (s_empty or s_e_p);
  s_pop           <= s_valid_ok;
  data_o.stall    <= s_stall;
  
  s_error_i                 <= error_i;
  s_stall_i                 <= stall_i;
  s_status_V_i              <= status_V_ref_i;
  s_status_i                <= status_ref_i;
  
  cmd_fifo_out_empty_ref_o  <= s_cmd_fifo_out_empty;
  s_cmd_fifo_out_pop        <= cmd_fifo_out_pop_ref_i;

  cmd_FIFO_out : generic_async_fifo
  generic map(
    g_data_width          => 16,
    g_size                => 8,
    g_show_ahead          => true,
    g_with_rd_empty       => true,
    g_with_wr_almost_full => true,
    g_with_wr_full        => true)
  port map(
    rst_n_i               => rst_sys_n_i,
    we_i                  => s_cmd_fifo_out_push,
    rd_i                  => s_cmd_fifo_out_pop,
    rd_empty_o            => s_cmd_fifo_out_empty,
    wr_full_o             => s_cmd_fifo_out_full,
    clk_wr_i              => clk_sys_i,
    clk_rd_i              => clk_ref_i,
    d_i                   => r_cmd,
    q_o                   => cmd_ref_o);

  ch_sel_o                  <= r_ch_sel;
  clear_fifo_o              <= r_clear_fifo;
  ts_out_RD_o               <= r_ts_out_RD;
  s_ts_out_V_i              <= ts_out_V_i;
  s_ts_out_i                <= ts_out_i;
  s_cnt_V_i                 <= cnt_V_i;
  s_cnt_i                   <= cnt_i;
  ts_flags_o                <= r_ts_flags;
  
  data : process(clk_sys_i)
  begin
    if rising_edge(clk_sys_i) then
      if(rst_sys_n_i = '0') then
        r_e           <= '0';
        r_e_wait      <= '0';
        r_valid_check <= '0';
        r_error             <= std_logic_vector(to_unsigned(0, 1));
        r_status            <= (others => '0');
        r_cmd               <= (others => '0');
        s_cmd_fifo_out_push <= '0';
        r_ch_qty            <= std_logic_vector(to_unsigned(g_channels, 5));
        r_ch_sel            <= (others => '0');
        r_clear_fifo        <= mrst(r_clear_fifo);
        r_ts_out_RD         <= std_logic_vector(to_unsigned(0, 1));
        r_ts_out            <= mrst(r_ts_out);
        r_cnt               <= mrst(r_cnt);
        r_ts_flags          <= mrst(r_ts_flags);
      else
        r_e           <= s_e;
        r_a_ext0      <= s_a_ext;
        r_a_ext1      <= r_a_ext0;
        r_e_wait      <= s_e_p and not s_valid_ok;
        r_valid_check <= (r_valid_check or (s_e_p and not stall_i(0))) and not s_valid_ok;
        r_ack         <= s_pop and not (error_i(0) or r_error(0));
        r_err         <= s_pop and     (error_i(0) or r_error(0));
        data_o.ack    <= r_ack;
        data_o.err    <= r_err;
        
        
        if stall_i = "0" then
          r_clear_fifo  <= mrst(r_clear_fifo);
          r_error       <= (others => '0');
          r_ts_out_RD   <= (others => '0');
        end if;
        
        if s_cnt_V_i    = "1" then r_cnt    <= s_cnt_i; end if;     -- 
        if s_status_V_i = "1" then r_status <= s_status_i; end if;  -- 
        if s_ts_out_V_i = "1" then r_ts_out <= s_ts_out_i; end if;  -- 
        s_cmd_fifo_out_push                 <= '0';
        r_p <= to_integer(unsigned(r_ch_sel));

        
        if(s_e = '1') then
          if(s_w = '1') then
            -- WISHBONE WRITE ACTIONS
            case to_integer(unsigned(s_a_ext)) is
              when c_cmd_OWR        => r_cmd    <= f_wb_wr(r_cmd, s_d, s_s, "owr");                                 -- 
              r_stall(0)                        <= r_stall(0) or s_cmd_fifo_out_almost_full;
              s_cmd_fifo_out_push               <= '1';
              when c_ch_sel_RW      => r_ch_sel <= f_wb_wr(r_ch_sel, s_d, s_s, "owr");                              -- 
              when c_clear_fifo_OWR => mset(r_clear_fifo, f_wb_wr(mget(r_clear_fifo, r_p), s_d, s_s, "owr"), r_p);  -- 
              r_stall                           <= (others    => '1');
              when c_ts_flags_RW    => mset(r_ts_flags, f_wb_wr(mget(r_ts_flags, r_p), s_d, s_s, "owr"), r_p);      -- 
              when others           => r_error  <= "1";
            end case;
          else
            -- WISHBONE READ ACTIONS
            case to_integer(unsigned(s_a_ext)) is
              when c_status_GET       => null;
              when c_ch_qty_GET       => null;
              when c_ch_sel_RW        => null;
              when c_ts_out_GET_0     => null;
              r_ts_out_RD <= (others  => '1');
              when c_ts_out_GET_1     => null;
              r_ts_out_RD <= (others  => '1');
              when c_cnt_GET          => null;
              when c_ts_flags_RW      => null;
              when others             => r_error <= "1";
            end case;
          end if; -- s_w
        end if; -- s_e
        
        case to_integer(unsigned(r_a_ext1)) is
          when c_status_GET     => data_o.dat <= std_logic_vector(resize(unsigned(r_status), data_o.dat'length));                         -- 
          when c_ch_qty_GET     => data_o.dat <= std_logic_vector(resize(unsigned(r_ch_qty), data_o.dat'length));                         -- 
          when c_ch_sel_RW      => data_o.dat <= std_logic_vector(resize(unsigned(r_ch_sel), data_o.dat'length));                         -- 
          when c_r_ts_out_GET_0 => data_o.dat <= std_logic_vector(resize(unsigned(mget(ts_out, v_p)(31 downto 0)), data_o.dat'length));   -- 
          when c_r_ts_out_GET_1 => data_o.dat <= std_logic_vector(resize(unsigned(mget(ts_out, v_p)(63 downto 32)), data_o.dat'length));  -- 
          when c_r_cnt_GET      => data_o.dat <= std_logic_vector(resize(unsigned(mget(cnt, v_p)), data_o.dat'length));                   -- 
          when c_r_ts_flags_RW  => data_o.dat <= std_logic_vector(resize(unsigned(mget(ts_flags, v_p)), data_o.dat'length));              -- 
          when others           => data_o.dat <= (others => 'X');
        end case;

        
      end if; -- rst
    end if; -- clk edge
  end process;

end rtl;
